data.inputSchema:
{
  "schemaVersion": 1,
  "title": "X Tweet Scraper input",
  "description": "Scrape posts from URLs, profiles, searches, Lists, threads, replies, quote Tweets, articles, and media. Look up Tweets in batches, translate them, get their embed HTML, or collect retweeters and likers. Profile likes and likers are best effort.",
  "type": "object",
  "properties": {
    "startUrls": {
      "title": "Start URLs",
      "type": "array",
      "description": "Add Tweet, profile, search, or List URLs as strings or {\"url\":\"...\"} objects. Profile URLs may use /with_replies, /media, or best-effort /likes. For example, [\"https://x.com/elonmusk\", \"https://x.com/search?q=AI\"].",
      "editor": "json"
    },
    "twitterContent": {
      "title": "Search query",
      "type": "string",
      "description": "Search query using X advanced search syntax. Supports keywords, hashtags, exact phrases, boolean operators, and date or Unix time windows. Every returned tweet falls inside your dates. For example, web scraping OR #datascience.",
      "editor": "textfield",
      "example": "web scraping OR #datascience"
    },
    "searchTerms": {
      "title": "Search terms",
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Run multiple searches in one Actor run. Max Items applies across the run. Every result matches the date and Unix time operators in its term. For example, from:elonmusk AI, #bitcoin lang:en.",
      "editor": "stringList",
      "prefill": [
        "(AI agent OR coding agent OR agentic AI) (launch OR release OR benchmark OR open source) lang:en -filter:nativeretweets"
      ],
      "example": [
        "from:elonmusk AI",
        "#bitcoin lang:en"
      ]
    },
    "twitterHandles": {
      "title": "X handles",
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "X usernames whose posts to collect. Profile Tweets returns posts, reposts & the author's replies to their own posts. Add Exclude replies under Tweet type filters for original posts only. Profile With Replies keeps target-authored posts and replies. Add usernames with or without @. For example, elonmusk, @nasa.",
      "editor": "stringList",
      "example": [
        "elonmusk",
        "@nasa"
      ]
    },
    "profileUrls": {
      "title": "Profile URLs",
      "type": "array",
      "description": "Alias for Start URLs. Add profile URL strings or {\"url\":\"...\"} objects.",
      "editor": "json"
    },
    "tweetIds": {
      "title": "Tweet IDs",
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Tweet IDs or tweet URLs to look up directly. The run skips any other entry at no charge. Other sources in the same input run too, and Max Items applies across the run. There is no fixed ID count cap. For example, 20.",
      "editor": "stringList",
      "example": [
        "20"
      ]
    },
    "listIds": {
      "title": "List IDs",
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "X List IDs whose posts to collect. It is usually much faster than List URLs or the List ID filter below. For example, 1748648376080666720.",
      "editor": "stringList",
      "example": [
        "1748648376080666720"
      ]
    },
    "mode": {
      "title": "Mode",
      "type": "string",
      "description": "Auto picks a mode from your input. Choose a mode to force one. Profile Tweets returns posts, reposts & the author's replies to their own posts. Profile With Replies keeps target-authored posts and replies. Profile Mentions returns posts that mention each handle, newest first. Translation returns X's translation of each Tweet. Embed HTML returns the markup that embeds each Tweet. Top tweets returns the tweets X ranks highest by 1 metric over a day, week or month. Tweet modes without Tweet IDs use Search when query input is present.",
      "enum": [
        "legacy",
        "tweet",
        "tweets",
        "search",
        "profileTweets",
        "profileReplies",
        "profileMedia",
        "profileLikes",
        "profileMentions",
        "listTweets",
        "article",
        "replies",
        "quotes",
        "thread",
        "retweeters",
        "favoriters",
        "translation",
        "embed",
        "topTweets"
      ],
      "enumTitles": [
        "Auto",
        "Single Tweet",
        "Tweet IDs",
        "Search",
        "Profile tweets",
        "Profile With Replies",
        "Profile media",
        "Profile likes (best effort)",
        "Profile mentions",
        "List tweets",
        "Article",
        "Direct replies + coverage",
        "Quotes",
        "Thread",
        "Retweeters",
        "Likers (best effort)",
        "Translation",
        "Embed HTML",
        "Top tweets"
      ],
      "default": "legacy",
      "editor": "select",
      "errorMessage": {
        "enum": "Choose a supported mode."
      }
    },
    "maxItems": {
      "title": "Max items",
      "type": "integer",
      "description": "Optional result cap across the whole run. Leave empty to use your Apify max total charge as the result limit when set. Without a spend cap, Xquik uses its built-in default. The Apify pricing box shows the current per-result price before the run starts. Diagnostic rows count toward this cap. The form starts at 1,000. A run can return 100,000 rows & more, so raise it for a full export.",
      "minimum": 1,
      "editor": "number",
      "errorMessage": {
        "type": "Max Items must be a whole number.",
        "minimum": "Max Items must be at least 1."
      },
      "default": 100000,
      "prefill": 1000
    },
    "maxItemsPerTarget": {
      "title": "Max items per target",
      "type": "integer",
      "description": "Optional cap for each target in multi-target modes.",
      "minimum": 1,
      "editor": "number",
      "errorMessage": {
        "type": "Max Items Per Target must be a whole number.",
        "minimum": "Max Items Per Target must be at least 1."
      }
    },
    "queryType": {
      "title": "Sort by",
      "type": "string",
      "description": "Latest returns newest first. Top is ranked by relevance and is not exhaustive. Latest + Top returns both without duplicates and fills your limit from either. Account timelines ignore this setting.",
      "enum": [
        "Latest",
        "Top",
        "Latest + Top"
      ],
      "enumTitles": [
        "Latest",
        "Top",
        "Latest + Top"
      ],
      "default": "Latest",
      "prefill": "Latest + Top",
      "editor": "select",
      "errorMessage": {
        "enum": "Choose Latest, Top, or Latest + Top."
      }
    },
    "content": {
      "title": "Structured content filters",
      "type": "object",
      "description": "Build content filters without writing X search syntax.",
      "editor": "schemaBased",
      "properties": {
        "allWords": {
          "type": "string",
          "title": "All words",
          "description": "Words that should appear in the tweet text."
        },
        "exactPhrase": {
          "type": "string",
          "title": "Exact phrase",
          "description": "Exact phrase to search for."
        },
        "anyWords": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "title": "Any words",
          "description": "Any of these words may appear.",
          "editor": "stringList"
        },
        "excludeWords": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "title": "Exclude words",
          "description": "Words to exclude from results.",
          "editor": "stringList"
        },
        "hashtags": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "title": "Hashtags",
          "description": "Hashtags to include.",
          "editor": "stringList"
        },
        "cashtags": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "title": "Cashtags",
          "description": "Cashtags to include.",
          "editor": "stringList"
        }
      },
      "sectionCaption": "Common filters"
    },
    "users": {
      "title": "Structured user filters",
      "type": "object",
      "description": "Optional structured author, reply, mention, and list filters.",
      "editor": "schemaBased",
      "properties": {
        "from": {
          "type": "string",
          "title": "From user",
          "description": "Only include tweets from this username."
        },
        "to": {
          "type": "string",
          "title": "To user",
          "description": "Only include replies to this username."
        },
        "mention": {
          "type": "string",
          "title": "Mention user",
          "description": "Only include tweets mentioning this username."
        },
        "list": {
          "type": "string",
          "title": "List ID",
          "description": "Only include tweets from members of this list."
        }
      }
    },
    "time": {
      "title": "Date range",
      "type": "object",
      "description": "Keep posts from a date window. Use dates, Unix times, a recent window such as 2d, or post IDs.",
      "editor": "schemaBased",
      "properties": {
        "since": {
          "type": "string",
          "title": "Since date",
          "description": "Only include tweets on or after this date. Write YYYY-MM-DD, such as 2026-01-31. 31/01/2026 & 01/31/2026 also work. A date that fits both orders reads month first, so 04/01/2026 is 1 April. The Actor verifies each result."
        },
        "until": {
          "type": "string",
          "title": "Until date",
          "description": "Only include tweets before this date. It takes the same date forms as Since date. The Actor verifies each result."
        },
        "sinceTime": {
          "type": "string",
          "title": "Since Unix time",
          "description": "Only include tweets on or after this time. Write Unix seconds, such as 1767225600. An ISO 8601 time such as 2026-01-01T00:00:00Z works too, & so do the date forms of Since date. The Actor verifies each result."
        },
        "untilTime": {
          "type": "string",
          "title": "Until Unix time",
          "description": "Only include tweets before this time. It takes the same forms as Since Unix time. The Actor verifies each result."
        },
        "sinceId": {
          "type": "string",
          "title": "Since Tweet ID",
          "description": "Only include tweets newer than this ID."
        },
        "maxId": {
          "type": "string",
          "title": "Max Tweet ID",
          "description": "Only include tweets older than this ID."
        },
        "withinTime": {
          "type": "string",
          "title": "Within time",
          "description": "Only include tweets from the last time window."
        }
      }
    },
    "engagement": {
      "title": "Structured engagement filters",
      "type": "object",
      "description": "Optional structured engagement filters.",
      "editor": "schemaBased",
      "properties": {
        "minRetweets": {
          "type": "integer",
          "title": "Minimum retweets",
          "description": "Minimum retweet count.",
          "minimum": 0,
          "editor": "number"
        },
        "minLikes": {
          "type": "integer",
          "title": "Minimum likes",
          "description": "Minimum like count.",
          "minimum": 0,
          "editor": "number"
        },
        "minReplies": {
          "type": "integer",
          "title": "Minimum replies",
          "description": "Minimum reply count.",
          "minimum": 0,
          "editor": "number"
        },
        "maxRetweets": {
          "type": "integer",
          "title": "Maximum retweets",
          "description": "Only include tweets with at most this many retweets.",
          "minimum": 0,
          "editor": "number"
        },
        "maxLikes": {
          "type": "integer",
          "title": "Maximum likes",
          "description": "Only include tweets with at most this many likes.",
          "minimum": 0,
          "editor": "number"
        },
        "maxReplies": {
          "type": "integer",
          "title": "Maximum replies",
          "description": "Only include tweets with at most this many replies.",
          "minimum": 0,
          "editor": "number"
        }
      }
    },
    "media": {
      "title": "Structured media filters",
      "type": "object",
      "description": "Optional structured media filters.",
      "editor": "schemaBased",
      "properties": {
        "media": {
          "type": "boolean",
          "title": "Has media",
          "description": "Apply X's media search operator."
        },
        "images": {
          "type": "boolean",
          "title": "Has images",
          "description": "Apply X's image search operator."
        },
        "videos": {
          "type": "boolean",
          "title": "Has videos",
          "description": "Apply X's video search operator."
        },
        "links": {
          "type": "boolean",
          "title": "Has links",
          "description": "Apply X's link search operator."
        }
      }
    },
    "lang": {
      "title": "Language",
      "type": "string",
      "description": "Filter tweets by language using a 2-letter ISO 639-1 code. Every returned tweet matches this language.",
      "editor": "select",
      "example": "en",
      "enumSuggestedValues": [
        "en",
        "es",
        "ja",
        "fr",
        "de",
        "pt",
        "ru",
        "ar",
        "ko",
        "zh",
        "it",
        "tr",
        "nl",
        "pl",
        "hi",
        "id",
        "th",
        "vi",
        "sv",
        "fa"
      ],
      "enumTitles": [
        "English (en)",
        "Spanish (es)",
        "Japanese (ja)",
        "French (fr)",
        "German (de)",
        "Portuguese (pt)",
        "Russian (ru)",
        "Arabic (ar)",
        "Korean (ko)",
        "Chinese (zh)",
        "Italian (it)",
        "Turkish (tr)",
        "Dutch (nl)",
        "Polish (pl)",
        "Hindi (hi)",
        "Indonesian (id)",
        "Thai (th)",
        "Vietnamese (vi)",
        "Swedish (sv)",
        "Persian (fa)"
      ]
    },
    "tweetTypes": {
      "title": "Structured Tweet type filters",
      "type": "object",
      "description": "Optional tweet type filters. Include only one type, or exclude replies, reposts or quote tweets.",
      "editor": "schemaBased",
      "properties": {
        "replies": {
          "type": "boolean",
          "title": "Replies",
          "description": "Only include replies."
        },
        "quotes": {
          "type": "boolean",
          "title": "Quotes",
          "description": "Only include quote tweets."
        },
        "nativeRetweets": {
          "type": "boolean",
          "title": "Native retweets",
          "description": "Only include native retweets."
        },
        "blueVerified": {
          "type": "boolean",
          "title": "Blue verified",
          "description": "Only include Blue verified authors."
        },
        "safe": {
          "type": "boolean",
          "title": "Safe",
          "description": "Only include safe search results."
        },
        "news": {
          "type": "boolean",
          "title": "News",
          "description": "X no longer supports this filter. A search with it ends with a free diagnostic."
        },
        "excludeReplies": {
          "type": "boolean",
          "title": "Exclude replies",
          "description": "Drop replies, including the author's replies to their own posts. Use it with a profile to get original posts only."
        },
        "excludeRetweets": {
          "type": "boolean",
          "title": "Exclude reposts",
          "description": "Drop reposts (retweets)."
        },
        "excludeQuotes": {
          "type": "boolean",
          "title": "Exclude quote tweets",
          "description": "Drop quote tweets."
        }
      },
      "sectionCaption": "Additional filters"
    },
    "geo": {
      "title": "Structured geo filters",
      "type": "object",
      "description": "Optional structured location filters.",
      "editor": "schemaBased",
      "properties": {
        "near": {
          "type": "string",
          "title": "Near place",
          "description": "Keep tweets for a place, such as United States or San Francisco."
        },
        "within": {
          "type": "string",
          "title": "Within radius",
          "description": "X search no longer supports this filter. A run with it stops at once & says so. Use Near place alone."
        },
        "geocode": {
          "type": "string",
          "title": "Geocode",
          "description": "X search no longer supports this filter. A run with it stops at once & says so."
        }
      }
    },
    "cards": {
      "title": "Structured card filters",
      "type": "object",
      "description": "Optional structured card filters.",
      "editor": "schemaBased",
      "properties": {
        "name": {
          "type": "string",
          "title": "Card name",
          "description": "Keeps only tweets with this card type, such as poll2choice_text_only. The Actor checks each tweet."
        },
        "url": {
          "type": "string",
          "title": "URL",
          "description": "Only include tweets containing this URL or domain."
        }
      }
    },
    "sources": {
      "title": "Structured source filters",
      "type": "object",
      "description": "Optional structured source filters.",
      "editor": "schemaBased",
      "properties": {
        "source": {
          "type": "string",
          "title": "Source app",
          "description": "X search no longer supports this filter. A run with it stops at once & says so."
        },
        "excludeSource": {
          "type": "string",
          "title": "Exclude source app",
          "description": "X search no longer supports this filter. A run with it stops at once & says so."
        }
      }
    },
    "conversation_id": {
      "title": "Conversation ID",
      "type": "string",
      "description": "Only include tweets belonging to this conversation thread. Use the first tweet's ID in the thread.",
      "editor": "textfield"
    },
    "conversationIds": {
      "title": "Conversation IDs",
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Alias for one or more conversation_id searches.",
      "editor": "stringList"
    },
    "quoted_tweet_id": {
      "title": "Quoted Tweet ID",
      "type": "string",
      "description": "Only include tweets that quote this specific tweet ID.",
      "editor": "textfield"
    },
    "quoted_user_id": {
      "title": "Quoted user ID",
      "type": "string",
      "description": "Only include tweets that quote any tweet from this user ID.",
      "editor": "textfield"
    },
    "filter:has_engagement": {
      "title": "Has engagement",
      "type": "boolean",
      "description": "Only include tweets with at least one like, retweet, or reply.",
      "default": false
    },
    "include:nativeretweets": {
      "title": "Include native retweets",
      "type": "boolean",
      "description": "Include native retweets in results (excluded by default).",
      "default": false
    },
    "filter:twimg": {
      "title": "Has twimg",
      "type": "boolean",
      "description": "Only include tweets containing twimg.com images.",
      "default": false
    },
    "filter:native_video": {
      "title": "Has native video",
      "type": "boolean",
      "description": "Only include tweets with natively uploaded video.",
      "default": false
    },
    "filter:vine": {
      "title": "Has vine",
      "type": "boolean",
      "description": "X no longer supports this filter. A search with it ends with a free diagnostic.",
      "default": false
    },
    "filter:consumer_video": {
      "title": "Has consumer video",
      "type": "boolean",
      "description": "X no longer supports this filter. A search with it ends with a free diagnostic.",
      "default": false
    },
    "filter:pro_video": {
      "title": "Has pro video",
      "type": "boolean",
      "description": "X no longer supports this filter. A search with it ends with a free diagnostic.",
      "default": false
    },
    "filter:spaces": {
      "title": "Has spaces",
      "type": "boolean",
      "description": "Only include tweets containing a Spaces link.",
      "default": false
    },
    "filter:mentions": {
      "title": "Has mentions",
      "type": "boolean",
      "description": "Only include tweets containing @mentions.",
      "default": false
    },
    "filter:hashtags": {
      "title": "Has hashtags",
      "type": "boolean",
      "description": "Only include tweets containing hashtags.",
      "default": false
    },
    "outputVariant": {
      "title": "Output variant",
      "type": "string",
      "description": "Legacy preserves compatibility. Rich adds normalized public fields. Raw snapshot also adds a sanitized source snapshot. Compact and Full are Legacy aliases.",
      "enum": [
        "legacy",
        "rich",
        "raw",
        "compact",
        "full"
      ],
      "enumTitles": [
        "Legacy",
        "Rich",
        "Raw snapshot",
        "Compact (legacy alias)",
        "Full (legacy alias)"
      ],
      "default": "legacy",
      "prefill": "rich",
      "editor": "select",
      "errorMessage": {
        "enum": "Choose Legacy, Rich, Raw snapshot, or a Legacy alias."
      },
      "sectionCaption": "Output & profile options"
    },
    "fieldStyle": {
      "title": "Field style",
      "type": "string",
      "description": "Controls top-level and nested field names for rich and raw results, including reply diagnostics. Use camelCase for JavaScript and TypeScript. Use snake_case for Python, SQL, CSV, and warehouses. Legacy output ignores this setting. Raw snapshots keep source names. Dataset views select columns only. They do not rename data.",
      "enum": [
        "legacy",
        "camelCase",
        "snake_case"
      ],
      "enumTitles": [
        "Legacy",
        "camelCase",
        "snake_case"
      ],
      "default": "legacy",
      "prefill": "camelCase",
      "editor": "select",
      "errorMessage": {
        "enum": "Choose Legacy, camelCase, or snake_case."
      }
    },
    "outputPreset": {
      "title": "Output preset",
      "type": "string",
      "description": "Nested preserves the current object shape. Flat + nested also adds CSV-friendly author and media URL fields.",
      "enum": [
        "nested",
        "flat"
      ],
      "enumTitles": [
        "Nested",
        "Flat + nested"
      ],
      "default": "nested",
      "prefill": "flat",
      "editor": "select",
      "errorMessage": {
        "enum": "Choose Nested or Flat + nested."
      }
    },
    "includeSearchTerms": {
      "title": "Tag each result with its search term",
      "type": "boolean",
      "description": "Attach the first matching search term as `searchTerm` on each unique Tweet. Use it to identify which query produced each deduplicated result.",
      "default": false,
      "prefill": true
    },
    "respectProfileSubpages": {
      "title": "Respect profile subpages",
      "type": "boolean",
      "description": "Honor profile subpage paths such as /with_replies, /media, and /likes in profile URLs. /with_replies returns target-authored posts and replies. The Actor excludes conversation context from other authors.",
      "default": false
    },
    "articleTweetIds": {
      "title": "Article Tweet IDs",
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Tweet IDs to read with mode article.",
      "editor": "stringList",
      "sectionCaption": "Specialized targets"
    },
    "replyTweetIds": {
      "title": "Reply Tweet IDs",
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Tweet IDs whose direct replies to collect. Nested replies never count as direct. If replies look incomplete, the Actor adds a diagnostic when your limit allows. Real replies always come first.",
      "editor": "stringList"
    },
    "quoteTweetIds": {
      "title": "Quote Tweet IDs",
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Tweet IDs to read with mode quotes.",
      "editor": "stringList"
    },
    "threadTweetIds": {
      "title": "Thread Tweet IDs",
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Tweet IDs to read with mode thread.",
      "editor": "stringList"
    },
    "retweeterTweetIds": {
      "title": "Retweeter Tweet IDs",
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Tweet IDs to read with mode retweeters.",
      "editor": "stringList"
    },
    "favoriterTweetIds": {
      "title": "Favoriter Tweet IDs",
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Tweet IDs to read with mode favoriters. X may only expose liking users for eligible or owner-visible posts. If no users are available, the run status says so.",
      "editor": "stringList"
    },
    "topMetric": {
      "title": "Top tweets metric",
      "type": "string",
      "description": "What mode Top tweets ranks by. X lists up to 100 tweets for each metric.",
      "enum": [
        "likes",
        "replies",
        "quotes",
        "bookmarks",
        "shares",
        "views"
      ],
      "enumTitles": [
        "Likes",
        "Replies",
        "Quotes",
        "Bookmarks",
        "Shares",
        "Views"
      ],
      "default": "likes",
      "editor": "select",
      "sectionCaption": "Top tweets"
    },
    "topWindow": {
      "title": "Top tweets window",
      "type": "string",
      "description": "How far back mode Top tweets looks.",
      "enum": [
        "day",
        "week",
        "month"
      ],
      "enumTitles": [
        "Last day",
        "Last week",
        "Last month"
